CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('owner','admin')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
INSERT INTO public.user_roles(user_id,role) SELECT id,'owner' FROM auth.users WHERE id='f7d8f128-df81-43fd-a4fa-207dd7be6d21';
CREATE FUNCTION public.can_read_presale() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('owner','admin')) $$;
REVOKE ALL ON FUNCTION public.can_read_presale() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_read_presale() TO authenticated;
CREATE TABLE public.presale_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), first_name text NOT NULL CHECK(length(trim(first_name)) BETWEEN 1 AND 100), last_name text NOT NULL CHECK(length(trim(last_name)) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email)<=255 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), phone text CHECK(phone IS NULL OR (length(phone)<=30 AND phone ~ '^\+?[0-9 ()-]{6,30}$')), profession text NOT NULL CHECK(profession IN ('osteopath','kinesiologist','physiotherapist','other')), consent_privacy boolean NOT NULL CHECK(consent_privacy=true), privacy_version text NOT NULL DEFAULT 'presale-v1', honeypot text NOT NULL DEFAULT '' CHECK(honeypot=''), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.presale_leads TO anon,authenticated;
GRANT SELECT ON public.presale_leads TO authenticated;
GRANT ALL ON public.presale_leads TO service_role;
ALTER TABLE public.presale_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "submit presale interest" ON public.presale_leads FOR INSERT TO anon,authenticated WITH CHECK(consent_privacy=true AND honeypot='');
CREATE POLICY "owner admin read leads" ON public.presale_leads FOR SELECT TO authenticated USING(public.can_read_presale());
ALTER TABLE public.marketing_events DROP CONSTRAINT marketing_events_type_check;
ALTER TABLE public.marketing_events ADD CONSTRAINT marketing_events_type_check CHECK(type IN ('dormant','review','campaign','care_reminder'));
CREATE FUNCTION public.validate_followup_consent() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.type IN ('dormant','review','campaign') AND NOT EXISTS(SELECT 1 FROM public.patients WHERE id=NEW.patient_id AND therapist_id=NEW.therapist_id AND consent_marketing=true) THEN RAISE EXCEPTION 'Marketing consent required' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER followup_consent BEFORE INSERT OR UPDATE ON public.marketing_events FOR EACH ROW EXECUTE FUNCTION public.validate_followup_consent();
CREATE FUNCTION public.validate_custom_duration() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE minutes numeric; BEGIN IF NEW.service_type='custom' THEN minutes:=extract(epoch from (NEW.end_time-NEW.start_time))/60; IF minutes<10 OR minutes>240 OR mod(minutes,5)<>0 THEN RAISE EXCEPTION 'Invalid custom duration' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER custom_duration BEFORE INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.validate_custom_duration();